      ),
      hosts AS MATERIALIZED (
        
        SELECT DISTINCT referrer_host AS original, lower(rtrim(referrer_host, '.')) AS normalized
        FROM selected
        WHERE referrer_host IS NOT NULL AND length(rtrim(referrer_host, '.')) <= 253
      
      ),
      suffixes(original, candidate, depth) AS (
        SELECT original, normalized, 0 FROM hosts
        UNION ALL
        SELECT original, substr(candidate, instr(candidate, '.') + 1), depth + 1
        FROM suffixes WHERE instr(candidate, '.') > 0
      ),
      matches AS (
        SELECT original, excluded,
          row_number() OVER (PARTITION BY original ORDER BY priority DESC, length(rules.host) DESC,
            exact_host DESC) AS precedence
        FROM suffixes JOIN rules ON rules.host = suffixes.candidate
        WHERE exact_host = 0 OR depth = 0
      ),
      abusive_hosts AS MATERIALIZED (
        SELECT original FROM matches WHERE precedence = 1 AND excluded = 1
      ),
      assessed AS MATERIALIZED (
        SELECT selected.*,
          COALESCE(referrer_host IN (SELECT original FROM abusive_hosts), 0) AS referral_excluded
        FROM selected
      ),
      report_scope AS MATERIALIZED (
        SELECT * FROM assessed WHERE (NULL IS NULL OR path = NULL)
      ),
      included AS MATERIALIZED (
        SELECT * FROM report_scope WHERE referral_excluded = 0
      )
      ,
      sections(section, section_order) AS MATERIALIZED (
        VALUES ('totals', 0), ('path', 1), ('country', 2), ('series', 3), ('referrer', 4), ('device', 5), ('agent', 6), ('kind', 7), ('excluded', 8), ('referrer-state', 9), ('transitions', 10), ('referrer-details', 11), ('signer', 12), ('verification', 14)
      )
    SELECT section,
      CASE section
        WHEN 'totals' THEN (
          SELECT json_array(json_object(
            'views', COUNT(*), 'dailyClients', COUNT(DISTINCT daily_client_id),
            'unattributedViews', SUM(CASE WHEN referrer_host IS NULL THEN 1 ELSE 0 END)
          )) FROM included
        )
        WHEN 'path' THEN (
          SELECT COALESCE(json_group_array(json(row_json)), json('[]')) FROM (
            SELECT json_object('key1', path, 'views', COUNT(*),
              'dailyClients', COUNT(DISTINCT daily_client_id)) AS row_json
            FROM included GROUP BY path ORDER BY COUNT(*) DESC, path
          )
        )
        WHEN 'country' THEN (
          SELECT COALESCE(json_group_array(json(row_json)), json('[]')) FROM (
            SELECT json_object('key1', country, 'views', COUNT(*)) AS row_json
            FROM included WHERE country IS NOT NULL GROUP BY country ORDER BY COUNT(*) DESC, country
          )
        )
        WHEN 'series' THEN (
          SELECT COALESCE(json_group_array(json(row_json)), json('[]')) FROM (
            SELECT json_object('key1', strftime('%Y-%m-%dT%H:00:00Z', observed_at), 'views', COUNT(*),
              'dailyClients', COUNT(DISTINCT daily_client_id)) AS row_json
            FROM included GROUP BY strftime('%Y-%m-%dT%H:00:00Z', observed_at) ORDER BY strftime('%Y-%m-%dT%H:00:00Z', observed_at)
          )
        )
