            SELECT json_object('key1', referrer_host, 'views', COUNT(*)) AS row_json
            FROM included WHERE referrer_host IS NOT NULL
            GROUP BY referrer_host ORDER BY COUNT(*) DESC, referrer_host
          )
        )
        WHEN 'device' THEN (
          SELECT COALESCE(json_group_array(json(row_json)), json('[]')) FROM (
            SELECT json_object('key1', device_type, 'views', COUNT(*)) AS row_json
            FROM included GROUP BY device_type ORDER BY COUNT(*) DESC, device_type
          )
        )
        WHEN 'agent' THEN (
          SELECT COALESCE(json_group_array(json(row_json)), json('[]')) FROM (
            SELECT json_object('key1', agent_name, 'key2', traffic_class, 'views', COUNT(*)) AS row_json
            FROM included WHERE agent_name IS NOT NULL
            GROUP BY agent_name, traffic_class ORDER BY COUNT(*) DESC, agent_name
          )
        )
        WHEN 'kind' THEN (
          SELECT COALESCE(json_group_array(json(row_json)), json('[]')) FROM (
            SELECT json_object('key1', reader_kind, 'key2', CASE WHEN reader_kind = 'signed-agent' THEN CASE reader_reason WHEN 'https://crawler.exa.ai' THEN 'Exa' WHEN 'https://ahrefs.com' THEN 'Ahrefs' WHEN 'https://assistbot.duckduckgo.com' THEN 'DuckDuckGo' ELSE 'Other' END ELSE reader_reason END, 'views', COUNT(*),
              'dailyClients', COUNT(DISTINCT daily_client_id)) AS row_json
            FROM included WHERE reader_kind IS NOT NULL
            GROUP BY reader_kind, CASE WHEN reader_kind = 'signed-agent' THEN CASE reader_reason WHEN 'https://crawler.exa.ai' THEN 'Exa' WHEN 'https://ahrefs.com' THEN 'Ahrefs' WHEN 'https://assistbot.duckduckgo.com' THEN 'DuckDuckGo' ELSE 'Other' END ELSE reader_reason END ORDER BY COUNT(*) DESC, reader_kind, CASE WHEN reader_kind = 'signed-agent' THEN CASE reader_reason WHEN 'https://crawler.exa.ai' THEN 'Exa' WHEN 'https://ahrefs.com' THEN 'Ahrefs' WHEN 'https://assistbot.duckduckgo.com' THEN 'DuckDuckGo' ELSE 'Other' END ELSE reader_reason END
